<?php $flashSuccess=$_SESSION['success']??null; $flashError=$_SESSION['error']??null; $errors=$_SESSION['errors']??[]; $old=$_SESSION['old']??[]; unset($_SESSION['success'],$_SESSION['error'],$_SESSION['errors'],$_SESSION['old']); function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function urlFor($e,$a='list',$keys=[]){return '?'.http_build_query(array_merge(['entity'=>$e,'action'=>$a],$keys));} ?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hôtel Réservation</title><link rel="stylesheet" href="assets/style.css"></head><body>
<aside><a class="brand" href="index.php">Hotel<span>Desk</span></a><nav><a href="index.php" class="<?=!isset($_GET['entity'])?'active':''?>">Tableau de bord</a><?php foreach($entities as $name=>$item): ?><a class="<?=$entity===$name?'active':''?>" href="<?=h(urlFor($name))?>"><?=h($item['label'])?></a><?php endforeach ?></nav></aside><main><header><button class="menu" aria-label="Menu">☰</button><div><strong><?=isset($_GET['entity'])?h($meta['label']):'Tableau de bord'?></strong><small>Gestion des réservations hôtelières</small></div></header><section class="content">
<?php if($flashSuccess):?><div class="alert success"><?=h($flashSuccess)?></div><?php endif?><?php if($flashError):?><div class="alert error"><?=h($flashError)?></div><?php endif?><?php if($errors):?><div class="alert error"><?php foreach($errors as $error) echo '<div>'.h($error).'</div>';?></div><?php endif?>
<?php if(!isset($_GET['entity'])): ?><div class="page-head"><div><h1>Vue d’ensemble</h1><p>Accédez rapidement aux données de votre établissement.</p></div></div><div class="cards"><?php foreach($dashboard as $name=>$count):?><a class="card" href="<?=h(urlFor($name))?>"><span><?=h($entities[$name]['label'])?></span><b><?=$count?></b></a><?php endforeach?></div>
<?php elseif($action==='list'): ?><div class="page-head"><div><h1><?=h($meta['label'])?></h1><p>Consultez et gérez les enregistrements.</p></div><a class="btn primary" href="<?=h(urlFor($entity,'create'))?>">+ Ajouter</a></div><?php $rows=$model->all(); if(!$rows):?><div class="empty"><h2>Aucun enregistrement</h2><p>Commencez par ajouter un élément.</p><a class="btn primary" href="<?=h(urlFor($entity,'create'))?>">Ajouter</a></div><?php else:?><div class="table-wrap"><table><thead><tr><?php foreach(array_merge($meta['pk'],array_keys($meta['fields'])) as $f):?><th><?=h($meta['fields'][$f][0]??$f)?></th><?php endforeach?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach(array_merge($meta['pk'],array_keys($meta['fields'])) as $f):?><td><?php if($f==='mot_de_passe') echo '••••••••'; elseif(str_starts_with($f,'statut_')) echo '<span class="badge">'.h($row[$f]??'—').'</span>'; elseif(($meta['fields'][$f][1]??'')==='boolean') echo ($row[$f]??0)?'Oui':'Non'; else echo h($row[$f]??'—');?></td><?php endforeach?><td class="actions"><a href="<?=h(urlFor($entity,'show',$controller->keys($meta,$row)))?>">Voir</a><a href="<?=h(urlFor($entity,'edit',$controller->keys($meta,$row)))?>">Modifier</a><a class="danger" href="<?=h(urlFor($entity,'delete',$controller->keys($meta,$row)))?>">Supprimer</a></td></tr><?php endforeach?></tbody></table></div><?php endif?>
<?php elseif($action==='show'): ?><div class="page-head"><div><h1>Détails</h1><p><?=h($meta['label'])?></p></div><div><a class="btn" href="<?=h(urlFor($entity,'edit',$controller->keys($meta,$record)))?>">Modifier</a><a class="btn" href="<?=h(urlFor($entity))?>">Retour</a></div></div><div class="details"><?php foreach(array_merge($meta['pk'],array_keys($meta['fields'])) as $f):?><div><small><?=h($meta['fields'][$f][0]??$f)?></small><p><?= $f==='mot_de_passe'?'••••••••':h($record[$f]??'—') ?></p></div><?php endforeach?></div>
<?php elseif(in_array($action,['create','edit'],true)): $editing=$action==='edit'; $values=$editing?$record:$old; ?><div class="page-head"><div><h1><?=$editing?'Modifier':'Ajouter'?></h1><p><?=h($meta['label'])?></p></div><a class="btn" href="<?=h(urlFor($entity))?>">Retour</a></div><form class="form-card" method="post" novalidate><input type="hidden" name="form_action" value="<?=$editing?'edit':'create'?>"><?php if($editing) foreach($meta['pk'] as $pk):?><input type="hidden" name="<?=h($pk)?>" value="<?=h($record[$pk])?>"><?php endforeach?><div class="form-grid"><?php foreach($meta['fields'] as $name=>$field): [$label,$type,$required]=$field; $value=$values[$name]??''; ?><label class="field <?=($type==='textarea'?'wide':'')?>"><?=h($label)?><?=$required?'<em>*</em>':''?><?php if($type==='textarea'):?><textarea name="<?=h($name)?>"><?=h($value)?></textarea><?php elseif($type==='select'):?><select name="<?=h($name)?>" <?=$required?'required':''?>><option value="">Sélectionner…</option><?php foreach($field['options'] as $option):?><option <?=$value===$option?'selected':''?> value="<?=h($option)?>"><?=h($option)?></option><?php endforeach?></select><?php elseif($type==='relation'):?><select name="<?=h($name)?>" <?=$required?'required':''?>><option value="">Sélectionner…</option><?php foreach($options[$name] as $option):?><option <?=strval($value)===strval($option['id'])?'selected':''?> value="<?=h($option['id'])?>"><?=h($option['label'])?></option><?php endforeach?></select><?php elseif($type==='boolean'):?><span class="toggle"><input type="checkbox" name="<?=h($name)?>" value="1" <?=$value?'checked':''?>> Oui</span><?php else:?><input type="<?=$type==='password'?'password':h($type)?>" name="<?=h($name)?>" value="<?=$type==='password'?'':h($value)?>" <?=$required&&!($editing&&$type==='password')?'required':''?> <?=isset($field['step'])?'step="'.h($field['step']).'"':''?> <?=isset($field['min'])?'min="'.h($field['min']).'"':''?> <?=isset($field['max'])?'max="'.h($field['max']).'"':''?>><?php endif?></label><?php endforeach?></div><div class="form-actions"><button class="btn primary" type="submit">Enregistrer</button><a class="btn" href="<?=h(urlFor($entity))?>">Annuler</a></div></form>
<?php elseif($action==='delete'): ?><div class="modal-backdrop"><section class="modal"><h1>Supprimer cet élément ?</h1><p>Cette action est définitive. Les éléments liés peuvent empêcher la suppression.</p><form method="post"><?php foreach($meta['pk'] as $pk):?><input type="hidden" name="<?=h($pk)?>" value="<?=h($record[$pk])?>"><?php endforeach?><input type="hidden" name="form_action" value="delete"><button class="btn danger-btn">Supprimer</button><a class="btn" href="<?=h(urlFor($entity))?>">Annuler</a></form></section></div>
<?php else:?><div class="alert error">Erreur : <?=h($fatal??'Erreur inconnue')?></div><?php endif?></section></main><script src="assets/app.js"></script></body></html>
